(()=>{'use strict';const reduce=()=>matchMedia('(prefers-reduced-motion: reduce)').matches,panels={};
function open(key){const dialog=panels[key];if(!dialog)return;document.querySelectorAll('dialog[open]').forEach(d=>d.close());dialog.showModal();dialog.scrollTop=0;}
for(const [id,title] of [['calendar','Calendar'],['nutrition','Daily Fuel'],['journal','Meal journal']]){const section=document.getElementById(id),dialog=document.createElement('dialog');dialog.id=id+'DashboardDialog';dialog.className='dashboard-dialog';dialog.setAttribute('aria-labelledby',id+'DashboardTitle');dialog.innerHTML='<div class="dashboard-dialog-top"><h2 id="'+id+'DashboardTitle">'+title+'</h2><button type="button" class="close" aria-label="Close '+title+'">×</button></div>';dialog.append(section);document.body.append(dialog);panels[id]=dialog;dialog.querySelector('.close').onclick=()=>dialog.close();document.querySelectorAll('a[href="#'+id+'"]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();open(id);}));}
window.PagePanels={open};document.querySelector('.fuel-checkin')?.addEventListener('click',()=>panels.nutrition.close());
const my=document.createElement('section');my.id='myWorkouts';my.setAttribute('aria-labelledby','myWorkoutsHeading');document.querySelector('#routines').after(my);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let savedPlan=null,selected=0;
function load(){savedPlan=null;try{const record=JSON.parse(localStorage.getItem('form-fuel-routines-v1'));if(record&&RoutineBuilder.validateSaved(record)){const r=RoutineBuilder.generate(record.profile,record.variant);if(r.ok)savedPlan=r.plan;}}catch{}selected=0;render();}
function render(){my.innerHTML='<div class="section-heading"><div><div class="section-heading-copy"><p class="eyebrow">YOUR SAVED TRAINING PLAN</p><h2 id="myWorkoutsHeading">My Workout</h2><p class="section-description">'+(savedPlan?'Your saved sessions, ready whenever you train. Stored on this device.':'Save a routine to see your weekly workouts here.')+'</p></div></div><button type="button" class="secondary" id="editMyWorkout">'+(savedPlan?'Edit routine ↗':'Build my routine ↗')+'</button></div>';
my.querySelector('#editMyWorkout').onclick=()=>document.querySelector('#routineSetupDialog').showModal();if(!savedPlan){my.insertAdjacentHTML('beforeend','<div class="my-workout-empty"><span aria-hidden="true">↗</span><h3>Your training week belongs here.</h3><p>Open the routine studio, review your preferences, then choose “Save routine & add to calendar”.</p></div>');return;}
const weekday=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date().getDay()],today=savedPlan.days.find(d=>d.weekday===weekday);selected=Math.min(selected,savedPlan.days.length-1);my.insertAdjacentHTML('beforeend','<div class="my-workout-board"><div class="my-workout-overview"><div><p class="eyebrow">'+savedPlan.days.length+' SESSIONS PER WEEK</p><h3>'+ (today?'Today: '+esc(today.title):'Today: recovery / rest day')+'</h3><p>'+savedPlan.profile.minutes+' min session budget · '+esc({bodyweight:'Bodyweight only',dumbbells:'Dumbbells + bodyweight',gym:'Full gym'}[savedPlan.profile.equipment])+'</p></div><button type="button" class="primary" id="myWorkoutCalendar">View in calendar ↗</button></div><div class="my-workout-tabs" role="tablist" aria-label="Saved workout sessions">'+savedPlan.days.map((d,i)=>'<button type="button" role="tab" aria-selected="'+(i===selected)+'" aria-controls="myWorkoutSession" id="myWorkoutTab'+i+'" tabindex="'+(i===selected?'0':'-1')+'" data-my-day="'+i+'"><span>'+esc(d.weekday)+'</span>'+esc(d.title)+'</button>').join('')+'</div><div id="myWorkoutSession" role="tabpanel"></div></div>');my.querySelector('#myWorkoutCalendar').onclick=()=>open('calendar');my.querySelectorAll('[data-my-day]').forEach(b=>{b.onclick=()=>{selected=Number(b.dataset.myDay);renderSession();};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();selected=e.key==='Home'?0:e.key==='End'?savedPlan.days.length-1:(selected+(e.key==='ArrowLeft'?-1:1)+savedPlan.days.length)%savedPlan.days.length;renderSession();my.querySelector('#myWorkoutTab'+selected).focus();};});renderSession();}
function renderSession(){const d=savedPlan.days[selected],p=my.querySelector('#myWorkoutSession');p.setAttribute('aria-labelledby','myWorkoutTab'+selected);p.innerHTML='<div class="my-workout-session-heading"><h3>'+esc(d.title)+'</h3><span>≈ '+d.estimatedMinutes+' min · '+d.exercises.length+' exercises</span></div><p class="my-workout-warmup">Warm up for '+d.warmupMinutes+' min, then complete your sets with control.</p><ol class="my-workout-exercises">'+d.exercises.map((e,i)=>'<li><span class="my-workout-number">'+String(i+1).padStart(2,'0')+'</span><div><button type="button" class="routine-demo" data-demo="'+esc(e.id)+'" data-name="'+esc(e.name)+'">'+esc(e.name)+' <span>View demonstration ↗</span></button><p>'+e.sets+' sets × '+esc(e.reps)+' · '+e.rest+' sec rest'+(e.unilateral?' · both sides':'')+'</p></div></li>').join('')+'</ol><p class="my-workout-warmup">Finish with '+d.cooldownMinutes+' min of easy movement. Log the completed session in your calendar.</p>';my.querySelectorAll('[data-my-day]').forEach(b=>{const active=Number(b.dataset.myDay)===selected;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});}
document.addEventListener('routine:saved',load);addEventListener('storage',e=>{if(e.key==='form-fuel-routines-v1')load();});load();
const nav=document.querySelector('.header nav');const link=document.createElement('a');link.href='#myWorkouts';link.textContent='My Workout';nav.querySelector('[href="#routines"]').after(link);if(['#calendar','#nutrition','#journal'].includes(location.hash))requestAnimationFrame(()=>open(location.hash.slice(1)));
})();
